// 求每个位置右边第一个比它大的元素下标，没有则 -1
int[] nextGreater(int[] nums) {
    int n = nums.length;
    int[] res = new int[n];
    Arrays.fill(res, -1);

    // 栈里存「下标」，且从栈底到栈顶是递减的（栈顶最小）
    Deque<Integer> stack = new ArrayDeque<>();
    for (int i = 0; i < n; i++) {
        // 当前元素比栈顶大 → 栈顶那个位置的答案就是 i
        while (!stack.isEmpty() && nums[stack.peek()] < nums[i]) {
            res[stack.pop()] = i;
        }
        stack.push(i);
    }
    return res;
}

int[] dailyTemperatures(int[] t) {
