int[] dijkstra(int n, List<int[]>[] g, int src) {   // g[u] = {v, w}
    int[] dist = new int[n];
    Arrays.fill(dist, Integer.MAX_VALUE);
    dist[src] = 0;

    // 小顶堆存 {距离, 节点}，按距离排序
    PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[0] - b[0]);
    pq.offer(new int[]{0, src});

    while (!pq.isEmpty()) {
        int[] cur = pq.poll();
        int d = cur[0], u = cur[1];
        if (d > dist[u]) continue;      // 懒删除：这是过期的旧记录，直接跳过

        for (int[] e : g[u]) {
            int v = e[0], w = e[1];
            if (dist[u] + w < dist[v]) {
                dist[v] = dist[u] + w;
                pq.offer(new int[]{dist[v], v});
            }
        }
    }
    return dist;   // 仍是 MAX_VALUE 表示不可达
}

void floyd(int[][] dist) {   // dist 初始为邻接矩阵，无边填 INF，自己到自己填 0
    int n = dist.length;
    for (int k = 0; k < n; k++) {          // 中转点必须在最外层！
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (dist[i][k] == INF || dist[k][j] == INF) continue;  // 防溢出
                dist[i][j] = Math.min(dist[i][j], dist[i][k] + dist[k][j]);
            }
        }
    }
}

int[] bellmanFord(int n, int[][] edges, int src) {   // edges = {u, v, w}
    int INF = Integer.MAX_VALUE / 2;     // 别用 MAX_VALUE，加 w 会溢出
    int[] dist = new int[n];
    Arrays.fill(dist, INF);
    dist[src] = 0;

    for (int i = 0; i < n - 1; i++) {    // 最多松弛 n-1 轮
        boolean changed = false;
        for (int[] e : edges) {
            if (dist[e[0]] == INF) continue;
            if (dist[e[0]] + e[2] < dist[e[1]]) {
                dist[e[1]] = dist[e[0]] + e[2];
                changed = true;
            }
        }
        if (!changed) break;             // 提前收敛
    }
    return dist;
}

