// 通用 BFS：层数就是最短距离（边权都为 1 时）
int[] bfs(List<List<Integer>> g, int src) {
    int n = g.size();
    int[] dist = new int[n];
    Arrays.fill(dist, -1);
    dist[src] = 0;

    Deque<Integer> q = new ArrayDeque<>();
    q.offer(src);
    while (!q.isEmpty()) {
        int u = q.poll();
        for (int v : g.get(u)) {
            if (dist[v] != -1) continue;   // 入队时就标记，别等出队，否则会重复入队
            dist[v] = dist[u] + 1;
            q.offer(v);
        }
    }
    return dist;
}

boolean isBipartite(int[][] graph) {
    int n = graph.length;
    int[] color = new int[n];     // 0 = 未染色, 1 / -1 = 两种颜色

    for (int i = 0; i < n; i++) {
        if (color[i] != 0) continue;

        Deque<Integer> q = new ArrayDeque<>();
        q.offer(i);
        color[i] = 1;

        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v : graph[u]) {
                if (color[v] == 0) {
                    color[v] = -color[u];        // 染成相反颜色
                    q.offer(v);
                } else if (color[v] == color[u]) {
                    return false;                // 相邻同色 → 不是二分图
                }
            }
        }
    }
    return true;
}

// next[i] = pattern[0..i] 的最长「相等前后缀」长度
int[] buildNext(String p) {
    int[] next = new int[p.length()];
    int j = 0;
    for (int i = 1; i < p.length(); i++) {
        while (j > 0 && p.charAt(i) != p.charAt(j)) j = next[j - 1];  // 失配就往前跳
        if (p.charAt(i) == p.charAt(j)) j++;
        next[i] = j;
    }
    return next;
}

int kmp(String s, String p) {
    if (p.isEmpty()) return 0;
    int[] next = buildNext(p);
    int j = 0;
    for (int i = 0; i < s.length(); i++) {
        while (j > 0 && s.charAt(i) != p.charAt(j)) j = next[j - 1];
        if (s.charAt(i) == p.charAt(j)) j++;
        if (j == p.length()) return i - p.length() + 1;   // 找到，返回起始下标
    }
    return -1;
}

