class LRUCache {
    class Node {
        int key, val;
        Node prev, next;
        Node(int k, int v) { key = k; val = v; }
    }

    private final Map<Integer, Node> map = new HashMap<>();
    private final int capacity;
    // 虚拟头尾：省掉「链表为空 / 只有一个节点」的特判
    private final Node head = new Node(0, 0);
    private final Node tail = new Node(0, 0);

    public LRUCache(int capacity) {
        this.capacity = capacity;
        head.next = tail;
        tail.prev = head;
    }

    public int get(int key) {
        Node n = map.get(key);
        if (n == null) return -1;
        moveToHead(n);          // 用过就提到最前
        return n.val;
    }

    public void put(int key, int value) {
        Node n = map.get(key);
        if (n != null) {
            n.val = value;
            moveToHead(n);
            return;
        }
        if (map.size() == capacity) {
            Node last = tail.prev;   // 最久没用的
            remove(last);
            map.remove(last.key);    // 别忘了从 map 里删，否则内存泄漏
        }
        Node node = new Node(key, value);
        map.put(key, node);
        addToHead(node);
    }

    private void addToHead(Node n) {
        n.next = head.next; n.prev = head;
        head.next.prev = n; head.next = n;
    }
    private void remove(Node n) {
        n.prev.next = n.next;
        n.next.prev = n.prev;
    }
    private void moveToHead(Node n) { remove(n); addToHead(n); }
}

class MinStack {
    private final Deque<Integer> stack = new ArrayDeque<>();
    private final Deque<Integer> minStack = new ArrayDeque<>();   // 栈顶 = 当前最小值

    public void push(int value) {
        stack.push(value);
        // 辅助栈要同步压：新值更小就压新值，否则重复压当前最小值
        minStack.push(minStack.isEmpty() ? value : Math.min(value, minStack.peek()));
    }

    public void pop() {
        stack.pop();
        minStack.pop();     // 两边必须一起弹，否则最小值就对不上了
    }

    public int top()   { return stack.peek(); }
    public int getMin(){ return minStack.peek(); }
}

// 两个栈实现队列：in 负责进，out 负责出
class MyQueue {
    private final Deque<Integer> in = new ArrayDeque<>();
    private final Deque<Integer> out = new ArrayDeque<>();

    public void push(int x) { in.push(x); }

    public int pop() {
        move();
        return out.pop();
    }

    public int peek() {
        move();
        return out.peek();
    }

    public boolean empty() { return in.isEmpty() && out.isEmpty(); }

    private void move() {
        // 只有 out 空了才倒，否则顺序会乱
        if (out.isEmpty()) {
            while (!in.isEmpty()) out.push(in.pop());
        }
    }
}
